package id.unnes.bemfhunnes.auth;
import id.unnes.bemfhunnes.config.AppProperties; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.stereotype.Service; import jakarta.servlet.http.HttpServletRequest; import java.util.*;
@Service public class AuthService {private final JdbcTemplate db;private final AppProperties props;private final TokenService tokens;private final BCryptPasswordEncoder encoder=new BCryptPasswordEncoder();public AuthService(JdbcTemplate d,AppProperties p){db=d;props=p;tokens=new TokenService(p);} public void seed(){seed(props.getSuperadminEmail(),props.getSuperadminPassword(),"superadmin");seed(props.getAdminEmail(),props.getAdminPassword(),"admin");}private void seed(String email,String password,String role){if(email==null||email.isBlank()||password==null||password.isBlank())return;if(db.queryForObject("SELECT COUNT(*) FROM users WHERE email=?",Integer.class,email)==0)db.update("INSERT INTO users(email,password_hash,role) VALUES(?,?,?)",email,encoder.encode(password),role);} public Map<String,Object> login(String email,String password)throws Exception{var rows=db.queryForList("SELECT id,email,password_hash,role FROM users WHERE lower(email)=lower(?)",email);if(rows.isEmpty()||!encoder.matches(password,(String)rows.getFirst().get("password_hash")))throw new IllegalArgumentException("Email atau password salah.");var u=rows.getFirst();return Map.of("token",tokens.create(((Number)u.get("id")).longValue(),(String)u.get("email"),(String)u.get("role")),"user",Map.of("id",u.get("id"),"email",u.get("email"),"role",u.get("role")));} public Map<String,Object> user(HttpServletRequest req){String h=req.getHeader("Authorization");if(h==null||!h.startsWith("Bearer "))throw new SecurityException("Autentikasi diperlukan.");var claims=tokens.verify(h.substring(7));if(claims==null)throw new SecurityException("Sesi telah berakhir. Silakan masuk kembali.");return claims;} public void requireRole(HttpServletRequest req,String...roles){String role=(String)user(req).get("role");if(Arrays.stream(roles).noneMatch(role::equals))throw new SecurityException("Akses tidak diizinkan.");}}
